from pyspark.sql import functions as F
from pyspark.sql.window import Window


def solve(employees):
    by_pay = Window.partitionBy("department_id").orderBy("salary")
    return employees.select(
        "department_id",
        "employee_id",
        "salary",
        F.dense_rank().over(by_pay).alias("pay_step"),
    )
